<script setup>import {reactive,ref} from 'vue';import {actions,state} from '../../domain/prototypeStore.js';const f=reactive({title:'',type:'消防告警',location:'东区展厅',description:''}),file=ref(''),msg=ref('');const submit=()=>{const r=actions.reportIncident(f);msg.value=r.ok?`已提交 ${r.event.id}`:r.message;if(r.ok)Object.assign(f,{title:'',description:''})}</script>
<template><section class="h5-page"><div class="h5-module-hero"><span>报</span><h2>事件上报</h2><p>及时提交现场情况</p></div><p v-if="msg" class="action-message">{{msg}}</p><form class="h5-card form-stack" @submit.prevent="submit"><label>事件名称<input v-model="f.title"></label><label>事件类型<select v-model="f.type"><option v-for="x in state.configs['事件类型']" :key="x">{{x}}</option></select></label><label>发生地点<input v-model="f.location"></label><label>情况说明<textarea v-model="f.description" rows="3"></textarea></label><label class="mock-upload">选择演示图片<input type="file" accept="image/*" @change="file=$event.target.files[0]?.name||''"><small v-if="file">已选择：{{file}}　<button type="button" @click="file=''">移除</button></small></label><button class="primary-button active">提交事件</button></form></section></template>
